// ExecutionEnv adapter: pi-durable's FileSystem + Shell implemented on top of a Cua Space (Linux container).
// Everything goes through one primitive, `bash(command, {timeoutMs}) -> {stdout, stderr, exitCode, timedOut}`
// (default: spaceBash, which is non-streaming `/bin/sh -c`). Binary data travels as base64.
// Methods never throw; they return Result values (FileError / ExecutionError).
import { posix } from "node:path";
import { ExecutionError, FileError, LineScanner, err, ok } from "@earendil-works/pi-durable/env";
import { config } from "./config.mjs";

/** Largest file `openBinaryReader` loads into memory. */
export const MAX_READER_BYTES = 32 * 1024 * 1024;
/** Raw bytes per write command (base64 of 64 KiB stays far below the 128 KiB single-argument limit). */
export const WRITE_CHUNK_BYTES = 64 * 1024;
const DEFAULT_HOME = "/home/cua";
const DEFAULT_FS_TIMEOUT_MS = 120_000;
const DEFAULT_WATCH_INTERVAL_MS = 500;
const MAX_WATCH_ENTRIES = 20_000;
const STAT_BATCH = 200;
const CWD_MISSING = "tarsbot: working directory does not exist";
const ABORTED = Symbol("aborted");

// ---------------------------------------------------------------------------------------------------------------
// Pure helpers

/** Quote one word for POSIX sh (single-quote scheme). */
const q = (s) => `'${String(s).replaceAll("'", `'\\''`)}'`;

/** Quote an argv array into one shell command line. Empty strings become `''`. */
export function shellQuote(argv) {
  return Array.from(argv, q).join(" ");
}

// Bot registry: bots.json maps a Bot to its durable conversation and display config.
// A Bot = one ownerless Conversation + its pi.agent configuration (REQ-ARC-2).
import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { randomUUID } from "node:crypto";
import { config, defaultModel } from "./config.mjs";
import { ctx } from "./harness.mjs";

/** Tools a read-only fork (REQ-F07) may keep, by name. */
export const READ_ONLY_TOOLS = ["read", "desktop_screenshot", "desktop_elements", "desktop_windows", "web_search", "search_history"];

export class BotRegistry {
  /** @param {any} harness @param {{ path?: string|null }} [opts] path=null keeps the registry in memory */
  constructor(harness, opts = {}) {
    this.harness = harness;
    this.path = opts.path === undefined ? config.botsPath : opts.path;
    this.bots = this.#load();
  }

  #load() {
    if (!this.path || !existsSync(this.path)) return [];
    return JSON.parse(readFileSync(this.path, "utf8")).bots ?? [];
  }

  #save() {
    if (!this.path) return;
    mkdirSync(dirname(this.path), { recursive: true });
    const tmp = `${this.path}.tmp`;
    writeFileSync(tmp, JSON.stringify({ bots: this.bots }, null, 2));
    renameSync(tmp, this.path);
  }

  list() {
    return [...this.bots];
  }

  get(id) {
    return this.bots.find((b) => b.id === id || b.name === id);
  }

  /** Durable conversation handle for a Bot. */
  async conversation(id) {
    const bot = this.get(id);
    if (!bot) return undefined;
    return this.harness.conversation(bot.conversationId, ctx);
  }

